import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"SetOverRide 设置运行倍率","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetOverRide.md","filePath":"3. 指令/5. 设置指令/SetOverRide.md","lastUpdated":1778862643000}'),r={name:"3. 指令/5. 设置指令/SetOverRide.md"};function n(d,e,h,l,o,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="setoverride-设置运行倍率" tabindex="-1">SetOverRide 设置运行倍率 <a class="header-anchor" href="#setoverride-设置运行倍率" aria-label="Permalink to &quot;SetOverRide 设置运行倍率&quot;">​</a></h1><p>该指令用于<strong>设置机器人的全局运行倍率（Override）</strong>。它作为一个系数，直接作用于后续所有运动指令（如 <code>MovJ</code>、<code>MovL</code>）中设定的速度值。通过该指令，可以方便地在不修改具体点位速度的情况下，整体调整程序的运行节拍。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetOverRide(vf) SetOverRide(全局速度百分比)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>vf：全局速度 (%)</td><td>int / INT 变量</td><td>机器人运行的整体百分比系数。</td><td>取值范围：<strong>1 - 100</strong>。<br>实际运行速度 = 运动指令设定速度 × 全局速度倍率（vf）。</td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p><code>SetOverRide</code> 相当于示教器上的&quot;速度倍率&quot;控制器的软件指令版。它是一个状态指令，执行后会一直生效，直到再次被修改。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetOverRide</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>执行结果：</strong></p><p>虽然 <code>MovL</code> 指令中设定的速度是 1000mm/s，但由于全局倍率被设为 <strong>50%</strong>，机器人实际会以 <strong>500mm/s</strong> 的速度向 P1 点运动。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>安全调试</strong>：在程序初次自动运行或进入危险区域前，通过指令将速度降至较低水平（如 10%），确认无误后再恢复。</li><li><strong>节拍动态调整</strong>：根据生产线前段供料的速度，动态调整机器人的运行快慢。例如，当物料堆积时，将 <code>SetOverRide</code> 设为 100；当缺料时，降至 50 以节省能耗和机械磨损。</li><li><strong>分段调速</strong>：在空载行程使用 100% 速度，在负载或精细作业区域通过该指令一键降速。</li></ul>`,18)])])}const g=a(r,[["render",n]]);export{k as __pageData,g as default};
